function handleCheckout(req) {
  const user = validateToken(req)          // OK: cross-cutting (auth)
  const cart = await cartSvc.get(user.id)  // creep: business call
  const tax  = computeTax(cart, user.region) // creep: business logic IN the gateway
  const order = await orderSvc.create(cart, tax) // creep: orchestration
  return shapeMobileResponse(order)        // creep: response shaping per client
}
